from typing import List

class Solution:
    def minCost(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        # dp[r][c][dir]: dir 0 is came vertically (can move horizontally), dir 1 is came horizontally (can move vertically)
        INF = float('inf')
        dp = [[[INF, INF] for _ in range(n)] for _ in range(m)]
        dp[0][0][0] = grid[0][0]
        dp[0][0][1] = grid[0][0]

        for r in range(m):
            for c in range(n):
                # Move right from (r, c - 1): arrives horizontally (dir 1), must have come vertically (dir 0)
                if c > 0 and dp[r][c - 1][0] != INF:
                    dp[r][c][1] = min(dp[r][c][1], dp[r][c - 1][0] + grid[r][c])
                # Move down from (r - 1, c): arrives vertically (dir 0), must have come horizontally (dir 1)
                if r > 0 and dp[r - 1][c][1] != INF:
                    dp[r][c][0] = min(dp[r][c][0], dp[r - 1][c][1] + grid[r][c])

        ans = min(dp[m - 1][n - 1][0], dp[m - 1][n - 1][1])
        return ans if ans != INF else -1

#include <vector>
#include <algorithm>

class Solution {
public:
    int minCost(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        const int INF = 1e9;
        std::vector<std::vector<std::vector<int>>> dp(m, std::vector<std::vector<int>>(n, std::vector<int>(2, INF)));
        dp[0][0][0] = grid[0][0];
        dp[0][0][1] = grid[0][0];

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (c > 0 && dp[r][c - 1][0] != INF) {
                    dp[r][c][1] = std::min(dp[r][c][1], dp[r][c - 1][0] + grid[r][c]);
                }
                if (r > 0 && dp[r - 1][c][1] != INF) {
                    dp[r][c][0] = std::min(dp[r][c][0], dp[r - 1][c][1] + grid[r][c]);
                }
            }
        }

        int ans = std::min(dp[m - 1][n - 1][0], dp[m - 1][n - 1][1]);
        return ans >= INF ? -1 : ans;
    }
};

class Solution {
    public int minCost(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int INF = 1000000000;
        int[][][] dp = new int[m][n][2];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                dp[r][c][0] = INF;
                dp[r][c][1] = INF;
            }
        }
        dp[0][0][0] = grid[0][0];
        dp[0][0][1] = grid[0][0];

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (c > 0 && dp[r][c - 1][0] != INF) {
                    dp[r][c][1] = Math.min(dp[r][c][1], dp[r][c - 1][0] + grid[r][c]);
                }
                if (r > 0 && dp[r - 1][c][1] != INF) {
                    dp[r][c][0] = Math.min(dp[r][c][0], dp[r - 1][c][1] + grid[r][c]);
                }
            }
        }

        int ans = Math.min(dp[m - 1][n - 1][0], dp[m - 1][n - 1][1]);
        return ans >= INF ? -1 : ans;
    }
}

