var minCost = function(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = 1e9;
    const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => [INF, INF]));
    dp[0][0][0] = grid[0][0];
    dp[0][0][1] = grid[0][0];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (c > 0 && dp[r][c - 1][0] !== INF) {
                dp[r][c][1] = Math.min(dp[r][c][1], dp[r][c - 1][0] + grid[r][c]);
            }
            if (r > 0 && dp[r - 1][c][1] !== INF) {
                dp[r][c][0] = Math.min(dp[r][c][0], dp[r - 1][c][1] + grid[r][c]);
            }
        }
    }

    const ans = Math.min(dp[m - 1][n - 1][0], dp[m - 1][n - 1][1]);
    return ans >= INF ? -1 : ans;
};
